/**
 * One staged coaching batch, run end to end: expand each day's coach text,
 * compose the conversion with the app's ports, and hand it to the sequential
 * runner. The abort signal is checked between items by the runner.
 */
import type { Analytics } from "@kaiord/core";

import type {
  CoachingBatchProgress,
  CoachingBatchResult,
} from "../../application/coaching/run-coaching-batch";
import { runCoachingBatch } from "../../application/coaching/run-coaching-batch";
import type { PersistencePort } from "../../ports/persistence-port";
import type { ExpandActivity } from "../../types/coaching-expand-result";
import { createCoachingConvert } from "./coaching-batch-convert";
import { expandDays } from "./coaching-batch-expand";
import type { CoachingBatchPending } from "./coaching-batch-stage";

export type CoachingBatchDeps = {
  profileId: string;
  expandActivity: ExpandActivity;
  persistence: PersistencePort;
  analytics: Analytics;
};

export async function runCoachingBatchFlow(
  staged: CoachingBatchPending,
  deps: CoachingBatchDeps,
  onProgress: (progress: CoachingBatchProgress) => void,
  signal: AbortSignal
): Promise<CoachingBatchResult> {
  await expandDays(deps.expandActivity, staged.activities);
  const convert = createCoachingConvert({
    profileId: deps.profileId,
    provider: staged.provider,
    modelId: staged.modelId,
    persistence: deps.persistence,
    analytics: deps.analytics,
  });
  return runCoachingBatch(staged.activities, convert, onProgress, signal);
}
