/**
 * The weekly sync carries no descriptions, so the coach's text for each day
 * must be fetched before the AI can read it. One expansion per day covers
 * every session of that day; a failure is ignored here because the conversion
 * reports it with a typed reason.
 */
import type { CoachingActivity } from "../../types/coaching-activity";
import type { ExpandActivity } from "../../types/coaching-expand-result";

export const expandDays = async (
  expandActivity: ExpandActivity,
  activities: readonly CoachingActivity[]
): Promise<void> => {
  const seen = new Set<string>();
  for (const activity of activities) {
    if (seen.has(activity.date)) continue;
    seen.add(activity.date);
    await expandActivity(activity);
  }
};
