/**
 * The staging half of the Train2Go batch: hold the sessions awaiting the user's
 * cost confirmation, and drop them when the dialog is cancelled.
 */
import { useCallback, useState } from "react";

import { useToastContext } from "../../contexts/ToastContext";
import { useTranslate } from "../../i18n/use-translate";
import type { CoachingActivity } from "../../types/coaching-activity";
import {
  type CoachingBatchPending,
  stageCoachingBatch,
} from "./coaching-batch-stage";

export function useCoachingBatchStage() {
  const t = useTranslate("calendar");
  const toast = useToastContext();
  const [pending, setPending] = useState<CoachingBatchPending | null>(null);

  const stage = useCallback(
    async (activities: CoachingActivity[]) => {
      const staged = await stageCoachingBatch(activities);
      if (staged) setPending(staged);
      else toast.error(t("batch.noProvider"));
    },
    [toast, t]
  );

  const cancelRequest = useCallback(() => setPending(null), []);

  return { pending, setPending, stage, cancelRequest };
}
