/**
 * The "process week" action for the nav row, with the cost
 * confirmation it opens. It hides when the week has no running session or no
 * active Garmin route, and while a send runs; while its own AI batch runs it
 * stays visible and reports the progress instead.
 */
import { useTranslate } from "../../i18n/use-translate";
import { Button } from "../atoms/Button";
import { BatchCostConfirmation } from "../organisms/BatchCostConfirmation";
import type { CalendarRunAndSend } from "./use-calendar-workflow";

export function RunAndSendButton({
  runAndSend,
}: {
  runAndSend: CalendarRunAndSend;
}) {
  const t = useTranslate("calendar");
  const { batch } = runAndSend;
  if (!runAndSend.offered) return null;
  const label = batch.progress
    ? t("runAndSend.progress", {
        done: batch.progress.done,
        total: batch.progress.total,
      })
    : t("runAndSend.action");
  return (
    <>
      <BatchCostConfirmation
        open={Boolean(batch.pending)}
        provider={batch.pending?.provider ?? null}
        estimate={batch.pending?.estimate}
        workoutCount={batch.pending?.activities.length}
        onConfirm={batch.confirmStart}
        onCancel={batch.cancelRequest}
      />
      <Button
        size="sm"
        variant="secondary"
        onClick={runAndSend.start}
        disabled={batch.isProcessing}
        data-testid="calendar-run-and-send"
      >
        {label}
      </Button>
    </>
  );
}
