/**
 * What the Train2Go action will do with the week's runs. A session already
 * backed by a structured workout is sent as-is — no token spent; a session
 * with no workout, or one still `raw`, needs the AI first.
 */
import type { WorkoutState } from "../../types/calendar-enums";
import type { CoachingActivity } from "../../types/coaching-activity";
import { toPersistedCoachingActivityId } from "../../types/coaching-activity-record";
import type { WeekPushCandidate } from "../garmin-bulk/select-week-push-candidates";
import type { CoachingBatchResult } from "./run-coaching-batch";

export type CoachingRunRecord = { workoutId: string; state: WorkoutState };

/** Persisted coaching-activity id → the workout it already produced. */
export type CoachingRunRecords = Record<string, CoachingRunRecord>;

export type CoachingRunPlan = {
  /** Sessions the AI must structure before they can be sent. */
  pending: CoachingActivity[];
  /** Sessions already structured, sent without spending tokens. */
  ready: WeekPushCandidate[];
};

/** States `selectWeekPushCandidates` refuses to send. */
const UNSENDABLE = new Set<WorkoutState>(["skipped", "stale"]);

export const planCoachingRun = (
  sessions: readonly CoachingActivity[],
  records: CoachingRunRecords,
  profileId: string | null
): CoachingRunPlan => {
  const pending: CoachingActivity[] = [];
  const ready: WeekPushCandidate[] = [];
  if (!profileId) return { pending, ready };
  for (const session of sessions) {
    const record =
      records[toPersistedCoachingActivityId(profileId, session.id)];
    if (!record || record.state === "raw") {
      pending.push(session);
    } else if (!UNSENDABLE.has(record.state)) {
      ready.push({ workoutId: record.workoutId, date: session.date });
    }
  }
  return { pending, ready };
};

/**
 * The send list: what was already structured plus what the batch just
 * converted, keyed by workout id so a live-query refresh during the run
 * cannot duplicate an entry, in calendar order.
 */
export const selectCoachingRunCandidates = (
  plan: CoachingRunPlan,
  result: CoachingBatchResult
): WeekPushCandidate[] => {
  const byWorkoutId = new Map<string, WeekPushCandidate>();
  const converted = result.converted.map(({ workoutId, date }) => ({
    workoutId,
    date,
  }));
  for (const candidate of [...plan.ready, ...converted]) {
    byWorkoutId.set(candidate.workoutId, candidate);
  }
  return [...byWorkoutId.values()].sort((a, b) => a.date.localeCompare(b.date));
};
