/**
 * The visible week's runnable sessions, in calendar order. Which sessions
 * count as runs is injected: the platform sport vocabulary lives in the
 * adapter layer, so the application layer only decides ordering and the
 * coach-skip rule.
 */
import type { CoachingActivity } from "../../types/coaching-activity";

export type RunPredicate = (activity: CoachingActivity) => boolean;

export const selectCoachingRunSessions = (
  byDay: Record<string, readonly CoachingActivity[]>,
  isRun: RunPredicate
): CoachingActivity[] =>
  Object.values(byDay)
    .flat()
    .filter((a) => a.status !== "skipped" && isRun(a))
    .sort((a, b) => a.date.localeCompare(b.date));
