/**
 * Stage the Train2Go running batch: the `workout_generation` model for the
 * active profile. The sessions themselves come from the calendar's coaching
 * query, so this only resolves the provider that will spend the tokens.
 */
import type { LlmProviderConfig } from "../../store/ai-store-types";
import { resolveBatchModel } from "./batch-prepare";

export type CoachingBatchPrep =
  | { ok: true; provider: LlmProviderConfig; modelId: string }
  | { ok: false; reason: "no-provider" };

export async function prepareCoachingBatch(): Promise<CoachingBatchPrep> {
  const model = await resolveBatchModel();
  return model ? { ok: true, ...model } : { ok: false, reason: "no-provider" };
}
