/**
 * Runs the AI conversion of a week's coaching sessions one by one,
 * continue-on-failure, with cancellation between items. The conversion use
 * case is idempotent: a session whose workout is already structured resolves
 * without calling the model, so a rerun never re-bills a finished session.
 */
import type { CoachingActivity } from "../../types/coaching-activity";
import type { ConvertWithAiResult } from "./convert-coaching-activity-with-ai-types";

export type CoachingBatchProgress = { done: number; total: number };

export type ConvertedRun = {
  activityId: string;
  workoutId: string;
  date: string;
};

export type CoachingBatchResult = {
  converted: ConvertedRun[];
  failed: Array<{ activityId: string; reason: string }>;
  cancelled: boolean;
};

export type ConvertCoachingActivity = (
  activity: CoachingActivity,
  abortSignal: AbortSignal
) => Promise<ConvertWithAiResult>;

export async function runCoachingBatch(
  activities: readonly CoachingActivity[],
  convert: ConvertCoachingActivity,
  onProgress: (progress: CoachingBatchProgress) => void,
  signal: AbortSignal
): Promise<CoachingBatchResult> {
  const result: CoachingBatchResult = {
    converted: [],
    failed: [],
    cancelled: false,
  };
  onProgress({ done: 0, total: activities.length });

  for (let i = 0; i < activities.length; i++) {
    if (signal.aborted) {
      result.cancelled = true;
      break;
    }
    const activity = activities[i];
    if (!activity) continue;
    const outcome = await convert(activity, signal);
    if (outcome.ok) {
      result.converted.push({
        activityId: activity.id,
        workoutId: outcome.workoutId,
        date: activity.date,
      });
    } else {
      result.failed.push({ activityId: activity.id, reason: outcome.reason });
    }
    onProgress({ done: i + 1, total: activities.length });
  }

  return result;
}
