/**
 * The calendar's send workflow: the raw-workout batch (behind the empty-week
 * banners), the "Send week" state, and the Train2Go action that structures
 * the visible week's running coaching sessions with AI — only those that
 * still need it — and then sends them all to the Garmin calendar in one
 * gesture. The send list comes from the batch outcome, so a session whose AI
 * call failed is never pushed with stale content.
 */
import { useCallback, useMemo } from "react";

import {
  planCoachingRun,
  selectCoachingRunCandidates,
} from "../../application/coaching/coaching-run-candidates";
import type { useCoachingActivities } from "../../hooks/use-coaching-activities";
import { useCoachingRunSessions } from "../../hooks/use-coaching-run-sessions";
import { useCoachingWeekRecords } from "../../hooks/use-coaching-week-records";
import { toPersistedCoachingActivityId } from "../../types/coaching-activity-record";
import type { useCalendarData } from "./calendar-hooks";
import { useBatchState } from "./use-batch-state";
import { useCalendarSendWeek } from "./use-calendar-send-week";
import { useCoachingBatchState } from "./use-coaching-batch-state";

type CalendarData = ReturnType<typeof useCalendarData>;
type CoachingState = ReturnType<typeof useCoachingActivities>;

export type CalendarRunAndSend = {
  batch: ReturnType<typeof useCoachingBatchState>;
  offered: boolean;
  start: () => void;
};

export function useCalendarWorkflow(
  profileId: string | null,
  data: CalendarData,
  coaching: CoachingState
) {
  const batch = useBatchState(data.weekStart, data.weekEnd);
  const send = useCalendarSendWeek(profileId, data.weekId, data.workoutsByDay);
  const sessions = useCoachingRunSessions(coaching.byDay);
  const activityIds = useMemo(
    () =>
      profileId
        ? sessions.map((s) => toPersistedCoachingActivityId(profileId, s.id))
        : [],
    [sessions, profileId]
  );
  const records = useCoachingWeekRecords(profileId, activityIds);
  const plan = useMemo(
    () => planCoachingRun(sessions, records, profileId),
    [sessions, records, profileId]
  );
  const coachingBatch = useCoachingBatchState(
    profileId,
    coaching.expandActivity,
    (result) => {
      const candidates = selectCoachingRunCandidates(plan, result);
      if (candidates.length > 0) send.start(candidates);
    }
  );
  const start = useCallback(() => {
    if (plan.pending.length > 0) {
      void coachingBatch.stage(plan.pending);
      return;
    }
    if (plan.ready.length > 0) send.start(plan.ready);
  }, [plan, coachingBatch, send]);
  const runAndSend: CalendarRunAndSend = {
    batch: coachingBatch,
    // Only the Garmin route gates this action: the sessions it sends come from
    // the coaching plan, so a week with no workout row yet is still sendable.
    offered:
      send.routeActive && send.state.phase === "idle" && sessions.length > 0,
    start,
  };
  return { batch, send, runAndSend };
}
