/**
 * The workout each of the week's coaching activities already produced, live.
 *
 * The calendar's Train2Go action needs to know, per session, whether the AI
 * still has to run: a session with a structured workout is only sent, one
 * with no workout (or a `raw` one) is converted first. Reads
 * `sessionMatches` by activity id and resolves each match's workout state.
 */
import { useLiveQuery } from "dexie-react-hooks";
import { useMemo } from "react";

import type { CoachingRunRecords } from "../application/coaching/coaching-run-candidates";
import { usePersistence } from "../contexts/persistence-context";

export function useCoachingWeekRecords(
  profileId: string | null,
  activityIds: readonly string[]
): CoachingRunRecords {
  const persistence = usePersistence();
  const key = activityIds.join("|");
  const ids = useMemo(() => (key ? key.split("|") : []), [key]);

  const records = useLiveQuery(async () => {
    const out: CoachingRunRecords = {};
    if (!profileId || ids.length === 0) return out;
    const matches = await persistence.sessionMatch.listByActivityIds(
      profileId,
      ids
    );
    for (const match of matches) {
      const workout = await persistence.workouts.getById(match.workoutId);
      if (!workout) continue;
      out[match.coachingActivityId] = {
        workoutId: workout.id,
        state: workout.state,
      };
    }
    return out;
  }, [persistence, profileId, ids]);

  return records ?? {};
}
