/**
 * The running half of the Train2Go batch: progress, the abort controller and
 * the run itself. The staged plan is passed in already confirmed, so the
 * cost gate is never bypassed here.
 */
import { useCallback, useRef, useState } from "react";

import type {
  CoachingBatchProgress,
  CoachingBatchResult,
} from "../../application/coaching/run-coaching-batch";
import { useAnalytics } from "../../contexts";
import { usePersistence } from "../../contexts/persistence-context";
import { useToastContext } from "../../contexts/ToastContext";
import { useLatestRef } from "../../hooks/use-latest-ref";
import { useTranslate } from "../../i18n/use-translate";
import type { ExpandActivity } from "../../types/coaching-expand-result";
import { runCoachingBatchFlow } from "./coaching-batch-flow";
import { reportCoachingBatch } from "./coaching-batch-report";
import type { CoachingBatchPending } from "./coaching-batch-stage";

export function useCoachingBatchRun(
  profileId: string | null,
  expandActivity: ExpandActivity,
  onDone: (result: CoachingBatchResult) => void
) {
  const t = useTranslate("calendar");
  const persistence = usePersistence();
  const analytics = useAnalytics();
  const toast = useToastContext();
  const onDoneRef = useLatestRef(onDone);
  const [progress, setProgress] = useState<CoachingBatchProgress | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const abortRef = useRef<AbortController | null>(null);

  const run = useCallback(
    async (staged: CoachingBatchPending) => {
      if (!profileId) return;
      setIsProcessing(true);
      setProgress({ done: 0, total: staged.activities.length });
      const controller = new AbortController();
      abortRef.current = controller;
      try {
        const deps = { profileId, expandActivity, persistence, analytics };
        const result = await runCoachingBatchFlow(
          staged,
          deps,
          setProgress,
          controller.signal
        );
        reportCoachingBatch(result, staged.activities.length, t, toast);
        onDoneRef.current(result);
      } catch {
        toast.error(t("batch.error"));
      } finally {
        setIsProcessing(false);
        setProgress(null);
        abortRef.current = null;
      }
    },
    [profileId, expandActivity, persistence, analytics, t, toast, onDoneRef]
  );

  const cancel = useCallback(() => abortRef.current?.abort(), []);

  return { progress, isProcessing, run, cancel };
}
