/**
 * Wires one coaching activity's AI conversion for the calendar batch: the
 * use case with the app's persistence port, analytics and the provider's
 * `GenerateKrdPort`. The view-model id is SHORT (`source:sourceId`); the
 * persisted row keys on the COMPOSITE id, so it is rebuilt here.
 */
import type { Analytics } from "@kaiord/core";

import { convertCoachingActivityWithAi } from "../../application/coaching/convert-coaching-activity-with-ai";
import { buildGenerateKrdPort } from "../../application/coaching/generate-krd-port";
import type { ConvertCoachingActivity } from "../../application/coaching/run-coaching-batch";
import type { PersistencePort } from "../../ports/persistence-port";
import type { LlmProviderConfig } from "../../store/ai-store-types";
import { toPersistedCoachingActivityId } from "../../types/coaching-activity-record";

export type CoachingConvertDeps = {
  profileId: string;
  provider: LlmProviderConfig;
  modelId: string;
  persistence: PersistencePort;
  analytics: Analytics;
};

export const createCoachingConvert = (
  deps: CoachingConvertDeps
): ConvertCoachingActivity => {
  const now = () => new Date().toISOString();
  return (activity, abortSignal) =>
    convertCoachingActivityWithAi(
      {
        activityId: toPersistedCoachingActivityId(deps.profileId, activity.id),
        abortSignal,
      },
      {
        coaching: deps.persistence.coaching,
        workouts: deps.persistence.workouts,
        sessionMatches: deps.persistence.sessionMatch,
        transaction: deps.persistence.transaction,
        analytics: deps.analytics,
        generateKrd: buildGenerateKrdPort(deps.provider, deps.modelId, now),
        newWorkoutId: () => crypto.randomUUID(),
        newMatchId: () => crypto.randomUUID(),
        clock: now,
      }
    );
};
