/**
 * Stage the Train2Go running batch: the provider/model that will spend the
 * tokens plus the text-based cost estimate shown before the user commits.
 * `null` means the profile has no `workout_generation` model bound.
 */
import type { BatchCostEstimate } from "../../hooks/use-batch-cost-estimate";
import type { LlmProviderConfig } from "../../store/ai-store-types";
import type { CoachingActivity } from "../../types/coaching-activity";
import { estimateCoachingBatch } from "./coaching-batch-estimate";
import { prepareCoachingBatch } from "./coaching-batch-prepare";

export type CoachingBatchPending = {
  provider: LlmProviderConfig;
  modelId: string;
  activities: CoachingActivity[];
  estimate: BatchCostEstimate;
};

export async function stageCoachingBatch(
  activities: CoachingActivity[]
): Promise<CoachingBatchPending | null> {
  const prep = await prepareCoachingBatch();
  if (!prep.ok) return null;
  return {
    provider: prep.provider,
    modelId: prep.modelId,
    activities,
    estimate: estimateCoachingBatch(activities, prep.provider),
  };
}
