/**
 * The toast a finished coaching batch shows: a failure count when any session
 * failed, the converted count otherwise. Kept out of the hook so the hook stays
 * inside the per-function line cap; the toast API is passed in so the calls
 * keep the static first arguments R-PIIInterpolation requires.
 */
import type { CoachingBatchResult } from "../../application/coaching/run-coaching-batch";
import type { useToast } from "../../hooks/use-toast";
import type { Translate } from "../../i18n/use-translate";

export type CoachingBatchToast = Pick<
  ReturnType<typeof useToast>,
  "success" | "error"
>;

export const reportCoachingBatch = (
  result: CoachingBatchResult,
  total: number,
  t: Translate,
  toast: CoachingBatchToast
): void => {
  if (result.failed.length > 0) {
    toast.error(
      t("runAndSend.failed"),
      t("runAndSend.failedCount", { count: result.failed.length, total })
    );
    return;
  }
  toast.success(
    t("runAndSend.processed"),
    t("runAndSend.processedCount", { count: result.converted.length }),
    { duration: 3000 }
  );
};
