/**
 * Cost estimate for the Train2Go running batch: the sessions' coach text fed
 * through the same chars/3 heuristic the raw-workout batch uses, priced at
 * the provider's blended rate.
 */
import {
  estimateCost,
  estimateTextTokens,
} from "../../application/cost-estimation";
import { getProviderRate } from "../../application/provider-rates";
import type { BatchCostEstimate } from "../../hooks/use-batch-cost-estimate";
import type { LlmProviderConfig } from "../../store/ai-store-types";
import type { CoachingActivity } from "../../types/coaching-activity";

export const estimateCoachingBatch = (
  activities: readonly CoachingActivity[],
  provider: LlmProviderConfig
): BatchCostEstimate => {
  const tokens = estimateTextTokens(
    activities.map((a) => `${a.title}\n${a.description ?? ""}`)
  );
  return {
    tokens,
    costUsd: estimateCost(tokens, getProviderRate(provider.type)),
    providerLabel: provider.label,
  };
};
