/**
 * The visible week's running sessions, memoized for the calendar workflow.
 * The predicate comes from the Train2Go adapter, which is why this wrapper
 * lives in `hooks/`: components may not import adapters directly.
 */
import { useMemo } from "react";

import { isRunningT2GSport } from "../adapters/train2go/train2go-run-sport";
import { selectCoachingRunSessions } from "../application/coaching/coaching-run-sessions";
import type { CoachingActivity } from "../types/coaching-activity";

export function useCoachingRunSessions(
  byDay: Record<string, readonly CoachingActivity[]>
): CoachingActivity[] {
  return useMemo(
    () => selectCoachingRunSessions(byDay, isRunningT2GSport),
    [byDay]
  );
}
