/**
 * The two counts the calendar header and banners read off the week grid:
 * whether any day holds a workout, and how many workouts are ready to push.
 */
import type { WorkoutRecord } from "../../types/calendar-record";

export type WeekWorkoutCounts = {
  hasWeekWorkouts: boolean;
  readyCount: number;
};

export const weekWorkoutCounts = (
  workoutsByDay: Record<string, WorkoutRecord[]>
): WeekWorkoutCounts => {
  const days = Object.values(workoutsByDay);
  return {
    hasWeekWorkouts: days.some((workouts) => workouts.length > 0),
    readyCount: days.reduce(
      (total, workouts) =>
        total + workouts.filter((w) => w.state === "ready").length,
      0
    ),
  };
};
