/**
 * The Train2Go running batch: stage the sessions that still need AI behind a
 * cost confirmation, run them through the coaching AI conversion, and hand
 * the outcome to the send chain. A plan with nothing to convert never stages
 * a dialog — it is a pure send.
 */
import { useCallback } from "react";

import type { CoachingBatchResult } from "../../application/coaching/run-coaching-batch";
import type { ExpandActivity } from "../../types/coaching-expand-result";
import { useCoachingBatchRun } from "./use-coaching-batch-run";
import { useCoachingBatchStage } from "./use-coaching-batch-stage";

export type { CoachingBatchPending } from "./coaching-batch-stage";

export function useCoachingBatchState(
  profileId: string | null,
  expandActivity: ExpandActivity,
  onDone: (result: CoachingBatchResult) => void
) {
  const {
    pending,
    setPending,
    stage: stageBatch,
    cancelRequest,
  } = useCoachingBatchStage();
  const { progress, isProcessing, run, cancel } = useCoachingBatchRun(
    profileId,
    expandActivity,
    onDone
  );

  const confirmStart = useCallback(async () => {
    if (!pending) return;
    setPending(null);
    await run(pending);
  }, [pending, setPending, run]);

  return {
    pending,
    progress,
    isProcessing,
    stage: stageBatch,
    confirmStart,
    cancelRequest,
    cancel,
  };
}
