/**
 * Which coaching sessions are runs, decided by the platform sport key rather
 * than the display label. Lives in the adapter layer because the key
 * vocabulary is Train2Go's; `running`, `trail`, `sprint` and `canicross` all
 * resolve to KRD `sport: "running"`, while gym, swim, bike and rest do not.
 */
import type { CoachingActivity } from "../../types/coaching-activity";
import { resolveT2GSport } from "./train2go-krd-sport";

export const isRunningT2GSport = (activity: CoachingActivity): boolean =>
  resolveT2GSport(activity.sportKey ?? "")?.sport === "running";
